import type { Employee, EmployeeInput, GenericResponse } from "@/model/model";

const baseUrl = (
  process.env.NEXT_PUBLIC_API_BASE_URL?.trim() || "https://localhost:7047"
).replace(/\/+$/, "");

export const isDemoMode = false

const storageKey = "employee-app-key";
const employeesList: Employee[] = [
  { id: 1, name: "Abdul", department: "I.T", salary: 50000 },
  { id: 2, name: "Raheel", department: "Finance", salary: 65000 },
  { id: 3, name: "Samad", department: "HR", salary: 40000 },
];

export class ApiError extends Error {
  constructor(
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export const employeeAPI = {
  async list(signal?: AbortSignal): Promise<GenericResponse<Employee[]>> {
    signal?.throwIfAborted();
    if (isDemoMode) {
      return successResponse(
        readDemoEmployees(),
        "Employees loaded successfully.",
      );
    }

    const response = await GenericRequest<GenericResponse<Employee[]>>(
      "/List",
      "GET",
      undefined,
      signal,
    );
    return { ...response, data: parseEmployees(response.data) };
  },

  async get(
    id: string | number,
    signal?: AbortSignal,
  ): Promise<GenericResponse<Employee>> {
    signal?.throwIfAborted();
    const employeeId = parseId(id);
    if (isDemoMode) {
      return successResponse(
        findDemoEmployee(readDemoEmployees(), employeeId),
        "Employee loaded successfully.",
      );
    }

    const response = await GenericRequest<GenericResponse<Employee>>(
      `/GetById/${employeeId}`,
      "GET",
      undefined,
      signal,
    );
    return { ...response, data: parseEmployee(response.data) };
  },

  async create(
    data: EmployeeInput,
    signal?: AbortSignal,
  ): Promise<GenericResponse<number>> {
    signal?.throwIfAborted();
    if (isDemoMode) {
      const employees = readDemoEmployees();
      const id =
        employees.reduce(
          (highestId, employee) => Math.max(highestId, employee.id),
          0,
        ) + 1;
      if (!isEmployeeId(id)) {
        throw new ApiError("No additional employee IDs are available.", 409);
      }
      const employee = parseEmployee({ ...data, id });
      saveDemoEmployees([...employees, employee]);
      return successResponse(id, "Employee added successfully.", 201);
    }

    const response = await GenericRequest<GenericResponse<number>>(
      "/Add",
      "POST",
      { ...data, id: 0 },
      signal,
    );
    if (!isEmployeeId(response.data)) {
      throw new ApiError("The API returned an invalid employee ID.", 502);
    }
    return response;
  },

  async update(
    id: string | number,
    data: EmployeeInput,
    signal?: AbortSignal,
  ): Promise<GenericResponse<Employee>> {
    signal?.throwIfAborted();
    const employeeId = parseId(id);
    if (isDemoMode) {
      const employees = readDemoEmployees();
      const existing = findDemoEmployee(employees, employeeId);
      const updated = parseEmployee({ ...existing, ...data, id: employeeId });
      saveDemoEmployees(
        employees.map((employee) =>
          employee.id === employeeId ? updated : employee,
        ),
      );
      return successResponse(updated, "Employee updated successfully.");
    }

    const response = await GenericRequest<GenericResponse<Employee>>(
      "/Update",
      "PUT",
      { ...data, id: employeeId },
      signal,
    );
    return { ...response, data: parseEmployee(response.data) };
  },

  async delete(
    id: string | number,
    signal?: AbortSignal,
  ): Promise<GenericResponse<boolean>> {
    signal?.throwIfAborted();
    const employeeId = parseId(id);
    if (isDemoMode) {
      const employees = readDemoEmployees();
      findDemoEmployee(employees, employeeId);
      saveDemoEmployees(
        employees.filter((employee) => employee.id !== employeeId),
      );
      return successResponse(true, "Employee deleted successfully.");
    }

    const response = await GenericRequest<GenericResponse<boolean>>(
      `/Delete/${employeeId}`,
      "DELETE",
      undefined,
      signal,
    );
    if (typeof response.data !== "boolean") {
      throw new ApiError("The API returned an invalid deletion result.", 502);
    }
    if (!response.data) {
      throw new ApiError("The API did not delete the employee.", 409);
    }
    return response;
  },
};

async function GenericRequest<T>(
  path: string,
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE",
  body?: EmployeeInput | Employee,
  signal?: AbortSignal,
): Promise<T> {
  const response = await fetch(`${baseUrl}${path}`, {
    method,
    signal,
    cache: "no-store",
    headers: {
      Accept: "application/json",
      ...(body ? { "Content-Type": "application/json" } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  }).catch((error: unknown) => {
    if (signal?.aborted) throw error;
    throw new ApiError(
      "Could not reach the employee API. Check that the backend is running, its HTTPS certificate is trusted, and CORS allows this app.",
      0,
    );
  });
  const text = await response.text().catch((error: unknown) => {
    if (signal?.aborted) throw error;
    throw new ApiError(
      "The API response could not be read. Please try again.",
      response.ok ? 502 : response.status,
    );
  });
  signal?.throwIfAborted();
  let payload: unknown;
  try {
    payload = JSON.parse(text);
  } catch {
    payload = null;
  }
  const message =
    isRecord(payload) && typeof payload.message === "string"
      ? payload.message.trim()
      : "";

  if (!response.ok) {
    throw new ApiError(
      message ||
        `The API request failed (${response.status}). Please try again.`,
      response.status,
    );
  }

  if (
    method === "DELETE" &&
    (text.trim() === "" ||
      (!isRecord(payload) &&
        response.headers.get("Content-Type")?.startsWith("text/plain")))
  ) {
    return successResponse(
      true,
      text.trim() || "Employee deleted successfully.",
      response.status,
    ) as T;
  }

  if (
    !isRecord(payload) ||
    typeof payload.isSuccess !== "boolean" ||
    typeof payload.message !== "string" ||
    typeof payload.status !== "number" ||
    !Number.isInteger(payload.status)
  ) {
    throw new ApiError("The API returned an invalid response wrapper.", 502);
  }

  if (!payload.isSuccess || payload.status < 200 || payload.status >= 300) {
    throw new ApiError(
      message || "The employee operation failed.",
      payload.status,
    );
  }

  return payload as T;
}

function successResponse<T>(
  data: T,
  message: string,
  status = 200,
): GenericResponse<T> {
  return { data, isSuccess: true, message, status };
}

function readDemoEmployees(): Employee[] {
  let stored: string | null;
  try {
    if (typeof localStorage === "undefined") {
      throw new Error("Browser storage is unavailable.");
    }
    stored = localStorage.getItem(storageKey);
  } catch {
    throw new ApiError(
      "Demo data could not be read. Allow browser storage and try again.",
      0,
    );
  }

  if (stored === null) {
    const employees = employeesList.map((employee) => ({ ...employee }));
    saveDemoEmployees(employees);
    return employees;
  }

  try {
    return parseEmployees(JSON.parse(stored));
  } catch {
    throw new ApiError(
      "Stored demo data is invalid and could not be read.",
      502,
    );
  }
}

function saveDemoEmployees(employees: Employee[]) {
  try {
    localStorage.setItem(storageKey, JSON.stringify(employees));
  } catch {
    throw new ApiError(
      "Demo data could not be saved. Allow browser storage and try again.",
      0,
    );
  }
}

function findDemoEmployee(employees: Employee[], id: number): Employee {
  const employee = employees.find((item) => item.id === id);
  if (!employee) {
    throw new ApiError("Employee not found.", 404);
  }
  return employee;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isEmployeeId(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isInteger(value) &&
    value > 0 &&
    value <= 2_147_483_647
  );
}

function parseId(id: string | number): number {
  const value = Number(id);
  if ((typeof id === "string" && !/^\d+$/.test(id)) || !isEmployeeId(value)) {
    throw new ApiError("Invalid employee ID.", 400);
  }
  return value;
}

function parseEmployee(value: unknown): Employee {
  if (!isRecord(value)) {
    throw new ApiError("The API returned an invalid employee response.", 502);
  }

  const { id, name, department, salary, image } = value;
  if (
    !isEmployeeId(id) ||
    typeof name !== "string" ||
    typeof department !== "string" ||
    typeof salary !== "number" ||
    !Number.isFinite(salary) ||
    (image !== undefined && typeof image !== "string")
  ) {
    throw new ApiError("The API returned an invalid employee response.", 502);
  }
  return {
    id,
    name,
    department,
    salary,
    ...(typeof image === "string" ? { image } : {}),
  };
}

function parseEmployees(value: unknown): Employee[] {
  if (!Array.isArray(value)) {
    throw new ApiError("The API returned an invalid employee list.", 502);
  }

  const ids = new Set<number>();
  return value.map((item) => {
    const employee = parseEmployee(item);
    if (ids.has(employee.id)) {
      throw new ApiError("The API returned duplicate employee IDs.", 502);
    }
    ids.add(employee.id);
    return employee;
  });
}
